      "year": 111,
      "session": 3,
      "subject": "law",
      "sourceId": "law-11",
      "number": 31,
      "stem": "證券投資信託事業募集基金，應依證券投資信託基金管理辦法及證券投資信託契約之規定，運用基金資產，關於其運用基金資產之敘述，何者正確？",
      "options": [
        "每一基金投資於任一上市或上櫃公司股票之股份總額，不得超過該公司已發行股份總數之百分之五；所經理之全部基金投資於任一上市或上櫃公司股票之股份總額，不得超過該公司已發行股份總數之百分之五",
        "每一基金投資於任一上市或上櫃公司股票之股份總額，不得超過該公司已發行股份總數之百分之五",
        "每一基金投資於任一上市或上櫃公司承銷股票之總數，不得超過該次承銷總數之百分之三；所經理之全部基金投資同一次承銷股票之總數，不得超過該次承銷總數之百分之十",
        "每一基金投資於任一公司所發行無擔保公司債之總額，不得超過該公司所發行無擔保公司債總額之百分之五"
      ],
      "answer": [
        "C"
      ],
      "sourceIds": [
        "law-11"
      ],
      "sourceRefs": [
        {
          "chapterId": "law-11",
          "sectionIndex": 1
        }
      ]
