      "stem": "有關結構型商品的敘述，正確的有：甲.又稱連動型債券；乙.結合固定收益商品與選擇權商品的組合型式商品；丙.不需額外承擔風險而能獲取較高之收益；丁.股權連結商品及保本型商品皆屬於結構型商品",
